n0.content:
\begin{definition}
    \label{def:pattern_n}
    \lean{pattern_n}
    \leanok
        Fix $n \in \mathbb{N}^*$. A map $f : \{0,1,\ldots , n,n+1\} \times \mathbb{Z} \longrightarrow F$ is called
        an \textit{$F$-valued pattern of height n} if, 

        1) for all $m \in \mathbb{Z}$, $ f(0,m) = f (n+1,m) = 0$, 

        2) for all $m \in \mathbb{Z}$, $ f(1,m) = f (n,m) = 1$, and 

        3) for all $(i,m) \in \{1,2,\ldots , n\} \times \mathbb{Z}$, we have
        \begin{equation}\label{eq:diamond}
            f(i,m) f(i,m+1) = 1 + f(i+1,m) f(i-1, m+1).
        \end{equation}
    \end{definition}

n1.content:
\begin{lemma}
    \lean{pattern_nContinuant1,pattern_nContinuant2}
    \label{l:pattern_nContinuant}
    \uses{def:pattern_n}
    \leanok
    Let $f$ be a nowhere-zero $F$-valued pattern of height $n$. For all $m$, we have 
    \begin{align*}
        f(i+2,m) &= f(2,m+i) f(i+1,m) - f(i,m), \qquad i \in \{0, \ldots, n-1\} \\
        f (i,m) &= f (n-1,m) f (i+1,m-1) - f(i+2,m-2), \qquad i \in \{0,n-1\}. 
    \end{align*}
\end{lemma}

n3.content:
\begin{proposition}
    \label{prop:translationInvariance}
    \lean{translationInvariance}
    \uses{def:pattern_n, l:pattern_nContinuant}
    \leanok
    Let $f$ be a nowhere-zero $F$-valued pattern of height $n$. Then, for all $m \in \mathbb{Z}$ and all $i \in \{0,\ldots, n+1\}$, we have
    \[
        f(i,m) = f(i,m+n+1).
    \]
\end{proposition}

n5.content:
\begin{corollary}
    \label{cor:imageFinite}
    \lean{imageFinite}
    \uses{prop:translationInvariance}
    \leanok
    Let $f$ be a nowhere-zero $F$-valued pattern of height $n$. Then, ${\rm Im}(f) := \{f (i,m) : i \in \{1,\ldots, n\}, m \in \mathbb{Z}\}$ is
    a finite set. 
\end{corollary}

n7.content:
\begin{definition}
    \label{def:flute}
    \lean{flute}
    \leanok
    A sequence $(a_k)$, indexed by $\mathbb{N}^*$ and consisting of positive integers is called pandean if $a_1 = 1$ and 
    if, for every $k > 1$, we have
    \[
        a_k \mid a_{k-1} + a_{k+1}.
    \]
    Given a pandean sequence $(a_k)$, if there exists a positive integer $n$ such that $a_k = a_{k+n-1}$ for all $k\in \mathbb{N}$, 
    the tuple $(a_1, \ldots, a_n)$ is called a Pan flute, or simply a flute, of height $n$. The set of all flutes of a given height $n$ 
    is denoted Flute$(n)$.
\end{definition}

n8.content:
\begin{lemma}
    \label{l:nFluteNonEmpty}
    \lean{fluteSetNonEmpty,csteFlute}
    \uses{def:flute}
    \leanok
    For any positive integer $n$, the set Flute$(n)$ is non-empty.
\end{lemma}

n9.content:
\begin{proof}
    \leanok
    It is clear that the constant sequence consisting 
    entirely of ones is pandean, and such a pandean sequence gives rise to a flute of height $n$ for any $n$.
\end{proof}

n10.content:
\begin{lemma}
    \label{l:FibFlute}
    \lean{fib_flute_even,fib_flute_odd}
    \uses{def:flute}
    \leanok
    1) If $n$ is odd, the $n$-tuple 
    \[
        (F_2,F_4, F_6, \ldots, F_{n-1}, F_{n}, F_{n-2}, F_{n-4}, \ldots, F_5, F_3, F_1), 
    \]
    is a Pan flute of height $n$.

    2) If $n$ is even, the $n$-tuple 
    \[
        (F_2, F_4, F_6, \ldots, F_{n-2}, F_{n}, F_{n-1}, F_{n-3}, \ldots, F_5, F_3,F_1),
    \]
    is a Pan flute of height $n$. 
\end{lemma}

