n12.content:
\begin{lemma}
    \uses{def:flute}
    \label{lem:FluteReduction}
    \lean{FluteReduction}
    \leanok
    In a flute $(a_1, \ldots, a_n)$, one of the following two statements holds.

    1) $a_2 = 1$ or $a_{n-1} =1$.

    2) There exists an index $i \in \{2,\ldots, n-1\}$ such that $a_i = a_{i-1} + a_{i+1}$.
\end{lemma}

n14.content:
\begin{proposition}
    \uses{def:flute,lem:FluteReduction}
    \label{prop:FluteBounded}
    \lean{FluteBounded}
    \leanok
    Fix a positive integer $n$, and let $(a_1, \ldots, a_n) \in {\rm Flute}(n)$. 
    For any $i \in \{1,\ldots, n\}$, we have $a_i \leq F_n$. 
\end{proposition}

n16.content:
\begin{definition}
    \label{def:arith_fp}
    \uses{def:pattern_n} 
    \lean{arith_fp}
    \leanok
        A $\mathbb{Q}$-valued pattern of height $n$ is said to be an \textit{arithmetic frieze pattern} if it takes 
        values in $\mathbb{Z}_{>0}$. 
        We denote by Frieze$(n)$ the set of arithmetic frieze patterns of height $n$. 
\end{definition}

n17.content:
\begin{proposition}
    \uses{def:flute,def:arith_fp,prop:translationInvariance}
    \label{prop:friezeIffFlute}
    \lean{friezeToFlute,frieze_f,fluteToFrieze}
    \leanok
1) Let $f$ be an arithmetic frieze pattern of height $n$. For all $m \in \mathbb{Z}$, the $n$-tuple
\[
    (f (1,m), f (2,m), \ldots, f (n,m))
\]
is a flute of height $n$.

2) Given a flute $(a_1, \ldots, a_n)$, there exists a arithmetic frieze pattern $f$ of height $n$ such that
\[
    (f (1,0), \ldots, f (n,0)) = (a_1, \ldots, a_n).
\]
\end{proposition}

n19.content:
\begin{corollary}
    \label{c:arithFriezePatSetNonEmpty}
    \lean{arithFriezePatSetNonEmpty}
    \uses{l:nFluteNonEmpty, prop:friezeIffFlute}
    \leanok
    Fix a positive integer $n$. The set Frieze$(n)$ is non-empty.
\end{corollary}

n21.content:
\begin{theorem}
    \label{mainTheorem}
    \lean{main1,main2,main3}
    \leanok
    \uses{prop:FluteBounded, l:FibFlute, prop:friezeIffFlute,c:arithFriezePatSetNonEmpty}
    For all $n \geq 1$, we have 
    \[
        u_n = F_{n}.
    \]    
\end{theorem}
